<?xml version="1.0" encoding="UTF-8" standalone="no"?>
<mappingRoot xmlns="http://www.ibm.com/2008/ccl/Mapping" xmlns:map="default" domainID="com.ibm.msl.mapping.xml" domainIDExtension="mb" mainMap="true" targetNamespace="default" version="8.0.5.0">
    <input path="jar:file://!com/ibm/etools/mft/map/xsds/predefined/JsonDomainMsg.xsd" var="var1"/>
    <input derivedFrom="MB:JSON_schema_in_json_file" path="/JSONSchema.json" var="var"/>
    <output path="/FixedLength.xsd"/>
    <namespaces>
        <namespace kind="supplement" prefix="in" uri="http://www.ibm.com/iib/msl/json"/>
    </namespaces>
    <generation engine="xquery"/>
    <mappingDeclaration name="JSONtoFixedLength_Mapping">
        <input namespace="http://www.ibm.com/iib/msl/json" path="$var1/mb:msg(JSON,assembly,JSON,Properties)" var="ComIbmMessageAssembly_JSON">
            <cast derivedFrom="MB:JSON_TYPE" path="$ComIbmMessageAssembly_JSON/JSON/Data/type('anyType')" qualifier="{http://www.ibm.com/iib/msl/json}JSONArray_JSONSchema_JsonType" ref="var"/>
        </input>
        <output path="mb:msg(MessageFixedLength,assembly,DFDL,Properties)" var="ComIbmMessageAssembly_MessageFixedLength"/>
        <move>
            <input path="$ComIbmMessageAssembly_JSON/Properties"/>
            <output path="$ComIbmMessageAssembly_MessageFixedLength/Properties"/>
            <override>
                <assign value="{}:MessageFixedLength">
                    <output path="$ComIbmMessageAssembly_MessageFixedLength/Properties/MessageType"/>
                </assign>
            </override>
        </move>
        <foreach>
            <input path="$ComIbmMessageAssembly_JSON/JSON/spath('Data',2)/Item"/>
            <output path="$ComIbmMessageAssembly_MessageFixedLength/MessageFixedLength/Item"/>
            <move>
                <input path="LastName"/>
                <output path="LastName"/>
            </move>
            <move>
                <input path="FirstName"/>
                <output path="FirstName"/>
            </move>
            <move>
                <input path="Address"/>
                <output path="Address"/>
            </move>
            <move>
                <input path="DateOfBirth"/>
                <output path="DateOfBirth"/>
            </move>
        </foreach>
    </mappingDeclaration>
</mappingRoot>
